import { env } from 'node:process'
import { readFileSync } from 'node:fs'
import { expect, test } from '@playwright/test'
import AxeBuilder from '@axe-core/playwright'

// A2 review (17324039) UI check against API responses generated by the real
// services for fictional data (e2e/fixtures/a2-review): the organizer
// statement's $0 "Payment received, order unfulfilled" lines with their live
// return status and a long "not counted" adjustment, and the admin payout
// list's manual-transfer placeholder and dispatch warning. Set
// PAYOUT_QA_SCREENSHOTS=<dir> to save review screenshots.
const fixture = name => JSON.parse(readFileSync(new URL(`./fixtures/a2-review/${name}`, import.meta.url)))
const statement = fixture('statement-classified.json')
const payouts = fixture('admin-payouts-dispatch.json')
const shots = env.PAYOUT_QA_SCREENSHOTS
const json = (route, data) => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(data) })
const snap = (page, name) => shots ? page.screenshot({ path: `${shots}/${name}.png`, fullPage: true, scale: 'css' }) : null

async function base(page) {
  await page.emulateMedia({ reducedMotion: 'reduce' })
  await page.route('**/api/v1/**', route => json(route, {}))
  await page.route('**/api/v1/health', route => json(route, { status: 'ok' }))
  await page.route('**/api/v1/config', route => json(route, { launch_capabilities: {}, payment_mode: 'simulate',
    service_fee_percent: '5.0', service_fee_flat_cents: 100, organizer_payout_terms: null }))
}
async function noOverflow(page, width) {
  expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(width)
}

for (const width of [390, 1280]) {
  test.describe(`at ${width}px`, () => {
    test.beforeEach(async ({ page }) => { await page.setViewportSize({ width, height: 900 }); await base(page) })

    test('statement: $0 unfulfilled lines with their return status and the long not-counted adjustment', async ({ page }) => {
      await page.route(`**/api/v1/organizer/events/12/finance/payout_statement**`, route => json(route, statement))
      await page.goto('/dashboard/events/12/statement')
      await expect(page.getByTestId('statement-status')).toHaveText(statement.status_label)
      await expect(page.getByText('Payment received, order unfulfilled')).toHaveCount(2)
      await expect(page.getByText('Partly returned; the rest is owed to the buyer. Not part of your proceeds.')).toBeVisible()
      await expect(page.getByText('Owed to the buyer. Not part of your proceeds.', { exact: true })).toBeVisible()
      await expect(page.getByText('Adjustment on a payment returned to a buyer (not counted)')).toBeVisible()
      await expect(page.getByText(/kept on the statement at \$0 so the organizer can see it was not counted/)).toBeVisible()
      await expect(page.getByText(/is the buyer's money\. HåfaPass returns it to the buyer/)).toBeVisible()
      // The manual transfer finance has approved but not sent is not "on its way".
      await expect(page.getByText('HåfaPass is preparing a transfer of $20.00 to your bank account. It has not been sent yet.')).toBeVisible()
      await expect(page.getByText('$20.00 being prepared, not sent yet')).toBeVisible()
      await expect(page.getByText(/on its way/)).toHaveCount(0)
      const result = await new AxeBuilder({ page }).include('#payout-statement, main').analyze()
      expect(result.violations.filter(item => ['serious', 'critical'].includes(item.impact))).toEqual([])
      await noOverflow(page, width)
      await snap(page, `a2-statement-classified-${width}`)
    })

    test('admin payouts: the manual transfer is not sent yet, and the out-of-date one says do not send', async ({ page }) => {
      await page.route('**/api/v1/admin/payouts**', route => json(route, payouts))
      await page.goto('/admin/payouts')
      await expect(page.getByText('Bank transfer not recorded yet')).toHaveCount(2)
      await expect(page.getByText(/^Request manual_po_/)).toHaveCount(2)
      await expect(page.getByText(/Approval is current\. Send the transfer to the approved payee/)).toBeVisible()
      await expect(page.getByRole('status').filter({ hasText: 'Do not send this transfer' })).toBeVisible()
      await noOverflow(page, width)
      await snap(page, `a2-admin-payouts-dispatch-${width}`)
    })
  })
}
